"use strict";
// A constructor function with prototype methods needs a mutable object
// model (R2.1). Its helper package runs inside its island.
const { step } = require("ni-dep");
const { twice } = require("ni-typed");
function Counter() {
  this.count = 0;
}
Counter.prototype.add = function add(n) {
  this.count = step(this.count, twice(n));
};
Counter.prototype.total = function total() {
  return this.count;
};
exports.Counter = Counter;
